function initialCandidateActions(view,p,target,compare=true){
  const e=recruitmentTarget(view,p.id),ev=e?.evaluation,ready=ev?.teamId===target.id&&ev.ability?.every(Number.isFinite),n=negotiationStore(view)[negotiationId(view,p.id,'initial',target.id)],chk=initialSignCheck(view,p,target);
  return `<div class="controls">${compare?`<button class="ghost sm2" data-init-compare="${p.id}">${INITMK.comparison.ids.includes(p.id)?'비교 제외':'비교 추가'}</button>`:''}${!e?`<button class="ghost sm2" data-init-interest="${p.id}">관심 등록</button>`:''}<button class="ghost sm2" data-init-scout="${p.id}">스카우팅</button>${e&&!ready?`<button class="ghost sm2" data-init-evaluate="${p.id}"${knowledge(view,p)<35||!scoutAbilityRange(view,p).every(Number.isFinite)?' disabled':''}>${ev?'대상 스쿼드 재평가':'내부 평가'}</button>`:''}${ready&&chk.ok&&n?.status!=='open'?`<button class="primary sm2" data-init-negotiate="${p.id}">공식 협상</button>`:''}${n?.status==='open'?'<a href="#init-negotiations">진행 중인 협상으로 이동</a>':''}${e?`<label>우선순위<select data-init-priority="${p.id}" aria-label="${esc(p.name)} 영입 우선순위">${RECRUIT_PRIORITY.map(x=>`<option value="${x}"${e.priority===x?' selected':''}>${x}순위</option>`).join('')}</select></label><button class="ghost sm2" data-init-drop="${p.id}">후보 해제</button>`:''}</div><small class="hint">${!e?'관심 등록 후 내부 평가를 진행하세요.':!ready?`내부 평가에는 정보 35% 이상이 필요합니다 (현재 ${knowledge(view,p)}%).`:'대상 스쿼드 내부 평가 완료 · '+esc(ev.date||'날짜 없음')}${!chk.ok?' · '+esc(chk.reason):''}</small>`;
}
function initialCandidateCommand(db,state,pid,kind){
 const target=db.teams[state.target],p=db.players[pid];if(!p||!initialCandidateAllowed(db,target,p))return '현재 후보 또는 대상 스쿼드의 영입 권한이 없습니다';
 if(['evaluate','negotiate'].includes(kind)&&!scoutAbilityRange(initialCandidateView(db),p).every(Number.isFinite))return '관측 기량 자료가 부족해 평가·협상을 진행할 수 없습니다';
 if(kind==='interest')return mInterest(db,pid,'B');
 if(kind==='evaluate')return mEvaluateTarget(db,pid,target.id);
 if(kind==='negotiate')return initialStartNegotiation(db,pid,target.id);
 if(kind==='drop')return mDropInterest(db,pid);
 if(kind==='scout')return scoutPlayers(db,[pid],40,.1*psOf(db,managedTeam(db).region));
 return '지원하지 않는 영입 작업입니다';
}
// ===== LOL GM: first-season organization market UI =====
let INITMK=initialCandidateUiState();
function renderInitialRosterMarket(){
  initialCandidateContext(DB);
  if(DB.world?.phase!=='initial_roster'||!managedTeam(DB)||DB.world?.fired)return '<p class="empty">현재 구단의 초기 영입 권한이 없습니다.</p>';
  if(managedTeam(DB)?.parent)return renderAcademyRosterControl(managedTeam(DB),true);
  const view=initialCandidateView(DB),root=managedTeam(view),squads=setupTeamsForManager(view);if(!INITMK.target||!squads.some(t=>t.id===INITMK.target))INITMK.target=squads[0].id;
  const target=DB.teams[INITMK.target],R=DB.regions[target.region],openInitial=Object.values(negotiationStore(view)).filter(n=>n.status==='open'&&n.kind==='initial'&&squads.some(t=>t.id===n.teamId)),errors=initialOrganizationErrors(view,root);
  const page=initialCandidatePage(view,INITMK,target),free=page.rows.map(x=>x.p);INITMK.page=page.page;
  INITMK.selected=(INITMK.selected||[]).filter(id=>initialCandidateAllowed(DB,DB.teams[INITMK.target],DB.players[id])).slice(0,10);
  const cards=squads.map(t=>{const e=initialSquadErrors(view,t),lim=initialSquadLimits(view,t),pay=payroll(view,t);return `<section class="cfgcard"><div class="cfghead"><b>${esc(t.name)}</b><span class="${e.length?'warn':'hi'}">${t.roster.length}/${lim.max}명 · ${e.length?'미완성':'등록 가능'}</span></div><div class="fin"><div><span>연봉</span><b>${money(pay)}</b><small>예산 ${money(initialSalaryBudget(view,t))}</small></div><div><span>비로컬</span><b>${teamNonLocalCount(view,t)}/${nonLocalLimitForTeam(view,t)}</b></div></div>${e.length?`<p class="hint">${e.map(esc).join(' · ')}</p>`:''}${t.roster.length?t.roster.map(id=>{const p=DB.players[id];return `<div class="mrow"><span><span class="role">${ROLE_KO[p.role]}</span> <b>${esc(p.name)}</b> · ${p.age}세 · ${money(p.contract.salary)} · ${p.contract.years}년${p.contract.signingBonus?` · 계약금 ${money(p.contract.signingBonus)}`:''}</span><button class="ghost sm2" data-init-release="${p.id}">FA로 되돌리기</button></div>`}).join(''):'<p class="empty">아직 등록 선수가 없습니다.</p>'}</section>`}).join('');
  const rows=free.map(p=>{const e=recruitmentTarget(view,p.id),ev=e?.evaluation,evalHere=!!(ev&&ev.teamId===target.id),nid=negotiationId(view,p.id,'initial',target.id),n=negotiationStore(view)[nid],chk=initialSignCheck(view,p,target),stage=n&&n.status==='open'?'협상 중':evalHere?'내부 평가 완료':e?recruitStageLabel(e):'미등록';
    const actions=initialCandidateActions(page.view,p,target);
    return `<tr><td><input type="checkbox" data-init-select="${p.id}"${INITMK.selected.includes(p.id)?' checked':''} aria-label="${esc(p.name)} 선택"></td><td><span class="role">${ROLE_KO[p.role]}</span></td><td><button class="ghost sm2" data-init-detail="${p.id}">${esc(p.name)}</button><small class="hint"> · ${stage}</small></td><td>${esc((DB.regions[p.region]||{name:p.region}).name)}</td><td class="num">${p.age}</td><td class="num">${initialObservedRange(scoutAbilityRange(page.view,p))}</td><td>${initialObservedRange(scoutPotentialRange(page.view,p))}</td><td class="num">${p.reputation}</td><td class="num">${Number.isFinite(observedPlayerMarketValue(page.view,p))?money(observedPlayerMarketValue(page.view,p)):'정보 부족'}</td><td class="num">약 ${money(asking(view,p,target.region))}</td><td>${actions}${!chk.ok?`<small class="lo"> ${esc(chk.reason)}</small>`:''}</td></tr>`}).join('');
  return `<section class="teamhead"><h2>첫 시즌 로스터 구성</h2><p>${esc(root.name)}에서 커리어를 시작합니다. 모든 구단은 백지 로스터에서 출발하고, 글로벌 FA 시장에서 실제 협상을 거쳐 선수단을 구성합니다.</p></section>
  <section><h3>내 구단 조직</h3>${cards}</section>
  ${MSG?`<p class="msg" role="status">${esc(MSG)}</p>`:''}
  <section id="init-negotiations" tabindex="-1"><h3>진행 중인 계약 협상</h3>${renderNegotiations(squads.map(t=>t.id),view)}</section>
  <section><h3>FA 선수 풀</h3><div class="controls"><label>등록 스쿼드<select id="init-target">${squads.map(t=>`<option value="${t.id}"${t.id===INITMK.target?' selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>포지션<select id="init-role"><option value="ALL">전체</option>${ROLES.map(r=>`<option value="${r}"${INITMK.role===r?' selected':''}>${ROLE_KO[r]}</option>`).join('')}</select></label><label>범위<select id="init-scope"><option value="region"${INITMK.scope==='region'?' selected':''}>내 지역 출신</option><option value="overseas"${INITMK.scope==='overseas'?' selected':''}>다른 지역 출신</option><option value="all"${INITMK.scope==='all'?' selected':''}>전체</option></select></label></div>
  <div class="fin"><div><span>대상 스쿼드</span><b>${esc(target.name)}</b></div><div><span>연봉 예산</span><b>${money(initialSalaryBudget(view,target))}</b><small>${R.spendingRule==='sfr_top5'&&target.division===1?'SFR 상위 5인 기준 '+money(R.salaryCap)+' · 초과 가능(부담금)':'리그 하드캡 없음'}</small></div></div>
  ${initialCandidateControls(page)}<div class="controls"><button class="ghost" id="init-compare-open">관측 후보 비교 (${INITMK.comparison.ids.length}/3명)</button><span class="hint">비교 선택과 일괄 작업 선택은 별개입니다. 같은 조건에서 최대 3명을 검토합니다.</span></div>
  <div class="scroll"><table><thead><tr><th><input type="checkbox" id="init-all" aria-label="현재 페이지에서 최대 10명 선택"></th><th>포지션</th><th>선수</th><th>출신</th><th>나이</th><th>예상 기량</th><th>예상 잠재</th><th>명성</th><th>시장가치</th><th>요구 연봉</th><th>영입 절차</th></tr></thead><tbody>${rows||'<tr><td colspan="11" class="empty">조건에 맞는 FA 선수가 없습니다. 기량·이름·출신 지역 조건을 확인하세요.</td></tr>'}</tbody></table></div><div class="controls"><button class="ghost" id="init-batch-interest">선택 관심 등록</button><button class="ghost" id="init-batch-scout">선택 일괄 스카우팅</button><span id="init-selection-count" role="status">${INITMK.selected.length}/10명 선택 · 현재 페이지 밖 ${INITMK.selected.filter(id=>!free.some(p=>p.id===id)).length}명</span><span class="hint">필터 밖 선택도 유지됩니다. 대상 스쿼드 변경 시 초기화됩니다.</span></div>
  <p class="hint">예상 기량은 공개 평가입니다. 스카우팅하면 범위가 좁아집니다. 관심 등록 후 내부 평가와 계약 협상을 진행하세요.</p></section>
  ${initialCandidateDetail(page)}${initialComparisonPanel(DB,INITMK)}
  <section><h3>등록 마감</h3>${errors.length?`<p class="warn">${errors.map(esc).join(' / ')}</p>`:'<p class="hi">내 구단 로스터 규정을 모두 충족했습니다.</p>'}${openInitial.length?`<p class="warn">진행 중인 계약 협상 ${openInitial.length}건을 먼저 마무리해야 합니다.</p>`:''}<div class="controls"><button class="primary" id="init-final"${errors.length||openInitial.length?' disabled':''}>전 세계 로스터 확정 후 시즌 개막</button><span class="hint">확정하면 AI 구단도 남은 FA 풀에서 같은 계약·등록 핵심 규칙으로 선수단을 구성합니다.</span></div></section>`;
}
function bindInitialRosterMarket(){
  const contextDb=DB,contextWorld=DB.world,contextTarget=INITMK.target,contextSlot=typeof SLOT==='undefined'?null:SLOT;
  const current=()=>DB===contextDb&&DB.world===contextWorld&&INITMK.target===contextTarget&&(typeof SLOT==='undefined'?null:SLOT)===contextSlot&&DB.world?.phase==='initial_roster'&&!DB.world.fired&&!!managedTeam(DB)&&(managedTeam(DB).parent||initialCandidateAllowed(DB,DB.teams[INITMK.target]));
  const act=m=>{if(!current())return;MSG=m;saveDB();navKeepScroll()};
  if(!managedTeam(DB)?.parent){bindInitialCandidateExplorer();bindInitialComparison(current)}
  for(const kind of ['interest','scout','evaluate','negotiate','drop'])document.querySelectorAll('[data-init-'+kind+']').forEach(b=>b.onclick=()=>{if(!current())return;act(initialCandidateCommand(DB,INITMK,b.dataset['init'+kind[0].toUpperCase()+kind.slice(1)],kind));if(kind==='negotiate')requestAnimationFrame(()=>{if(current())document.getElementById('init-negotiations')?.focus()})});
  const selectedBoxes=()=>[...document.querySelectorAll('[data-init-select]')];
  const syncSelection=()=>{const visible=new Set(selectedBoxes().map(x=>x.dataset.initSelect));INITMK.selected=[...INITMK.selected.filter(id=>!visible.has(id)),...selectedBoxes().filter(x=>x.checked).map(x=>x.dataset.initSelect)].slice(0,10);const count=$('#init-selection-count');if(count)count.textContent=INITMK.selected.length+'/10명 선택';};
  selectedBoxes().forEach(x=>x.onchange=()=>{if(INITMK.selected.filter(id=>!selectedBoxes().some(b=>b.dataset.initSelect===id)).length+selectedBoxes().filter(b=>b.checked).length>10){x.checked=false;const count=$('#init-selection-count');if(count)count.textContent='한 번에 최대 10명만 선택할 수 있습니다.';return}syncSelection()});
  if($('#init-all'))$('#init-all').onchange=e=>{selectedBoxes().forEach((x,i)=>x.checked=e.target.checked&&i<10-INITMK.selected.filter(id=>!selectedBoxes().some(b=>b.dataset.initSelect===id)).length);syncSelection()};
  const initSelected=()=>current()?INITMK.selected.filter(id=>initialCandidateAllowed(DB,DB.teams[INITMK.target],DB.players[id])):[];
  if($('#init-batch-interest'))$('#init-batch-interest').onclick=()=>{const ids=initSelected();if(!ids.length)return act('선수를 선택하세요');for(const id of ids)initialCandidateCommand(DB,INITMK,id,'interest');act(ids.length+'명 관심 등록')};
  if($('#init-batch-scout'))$('#init-batch-scout').onclick=()=>{const ids=initSelected();if(!ids.length)return act('선수를 선택하세요');act(scoutPlayers(DB,ids,40,0.1*psOf(DB,DB.teams[managedTeamId(DB)].region)*ids.length))};
  document.querySelectorAll('[data-init-priority]').forEach(el=>el.onchange=()=>{if(current()&&initialCandidateAllowed(DB,DB.teams[INITMK.target],DB.players[el.dataset.initPriority]))act(mInterest(DB,el.dataset.initPriority,el.value))});
  document.querySelectorAll('[data-init-release]').forEach(b=>b.onclick=()=>{if(current())act(initialReleasePlayer(DB,b.dataset.initRelease))});
  bindNegotiationControls(act,current);
  const fin=$('#init-final');if(fin)fin.onclick=()=>{if(!current())return;try{finalizeInitialRosters(DB);MSG='';saveDB();nav();window.scrollTo(0,0)}catch(e){act(e.message||String(e))}};
}

