// ===== LOL GM: negotiation cards, contract terms and event binding =====
function contractTermsText(c){if(!c)return '';const b=c.bonuses||{},buyout=normalizeBuyoutClause(c.buyout),xs=[money(c.salary)+' 연봉',c.years+'년','방출 보장 '+Math.round(contractGuaranteeRate(c)*100)+'%'];if(c.signingBonus)xs.push('계약금 '+money(c.signingBonus));if(b.performance)xs.push('성과 '+money(b.performance));if(b.title)xs.push('우승 '+money(b.title));if(b.international)xs.push('국제전 '+money(b.international));if(buyout)xs.push((buyout.type==='release'?'구단 거부 불가 바이아웃 ':'협상 개시권 바이아웃 ')+money(buyout.amount));if(c.option)xs.push((c.option.type==='player'?'선수':'팀')+' 옵션');if(c.promisedRole)xs.push(SQUAD_ROLE_KO[c.promisedRole]||c.promisedRole);return xs.join(' · ')}
function renderNegotiations(teamIds=null,db=DB){
  const allowed=new Set(teamIds||[managedTeamId(db)]),negs=Object.values(negotiationStore(db)).filter(n=>allowed.has(n.teamId)&&n.status==='open');
  if(!negs.length)return '<p class="hint">진행 중인 공식 협상이 없습니다.</p>';
  return negs.map(n=>{const p=db.players[n.pid],team=db.teams[n.teamId],rivals=n.competitors?.length||0,
      duration=contractDurationPolicy(db,p,team);
    if(n.stage==='club'){const ask=n.clubCounter||sellerTransferAsk(db,p,db.teams[n.sellerId]);return `<div class="cfgcard"><div class="cfghead"><b>${esc(p.name)} · 이적료 협상</b><span class="hint">${esc(db.teams[n.sellerId]?.name||'원소속 구단')} · ${n.clubRounds||0}/3라운드</span></div><p class="hint">상대 역제안이 있을 때만 정확한 요구액을 확인할 수 있습니다.</p><div class="controls"><label>이적료 <input type="number" step="0.5" min="0" value="${ask}" data-neg-fee="${n.id}">억</label><button class="primary" data-neg-bid="${n.id}">제안</button>${n.clubCounter?`<button class="ghost" data-accept-seller="${n.id}">역제안 수락</button>`:''}<button class="ghost" data-neg-cancel="${n.id}">협상 종료</button></div>${transferFeeOfferFields(n.id)}</div>`}
    const c=n.counter||n.demand,b=c.bonuses||{};
    return `<div class="cfgcard"><div class="cfghead"><b>${esc(p.name)} · ${n.kind==='renewal'?'재계약':n.kind==='early_fa'?'조기 계약':n.kind==='initial'?(esc(db.teams[n.teamId]?.name||'')+' 창단 계약'):'개인조건'} 협상</b><span class="hint">${n.round}/${n.maxRounds}라운드 · 경쟁 관심 ${rivals}곳</span></div><p class="hint">협상 담당 · ${esc(n.representative?.name||playerRepresentativeText(p))}</p><p><b>${n.counter?'선수 측 역제안':'선수 측 초기 요구'}</b> · ${esc(contractTermsText(c))}</p>${n.feePlan?`<p class="hint">${esc(transferFeePlanText(n.feePlan))}</p>`:''}<div class="controls"><label>연봉 <input type="number" step="0.1" min="0.1" value="${c.salary}" data-neg-sal="${n.id}">억</label><label>기간 <select data-neg-years="${n.id}">${duration.choices.map(y=>`<option value="${y}"${c.years===y?' selected':''}>${y}년</option>`).join('')}</select></label><label>계약금 <input type="number" step="0.1" min="0" value="${c.signingBonus||0}" data-neg-sign="${n.id}">억</label><label>성과 보너스 <input type="number" step="0.1" min="0" value="${b.performance||0}" data-neg-perf="${n.id}">억</label><label>우승 보너스 <input type="number" step="0.1" min="0" value="${b.title||0}" data-neg-title="${n.id}">억</label><label>국제전 보너스 <input type="number" step="0.1" min="0" value="${b.international||0}" data-neg-intl="${n.id}">억</label><label>바이아웃 유형 <select data-neg-buyout-type="${n.id}"><option value="negotiation"${normalizeBuyoutClause(c.buyout)?.type!=='release'?' selected':''}>협상 개시권</option><option value="release"${normalizeBuyoutClause(c.buyout)?.type==='release'?' selected':''}>구단 거부 불가</option></select></label><label>바이아웃 금액 <input type="number" step="0.5" min="0" value="${normalizeBuyoutClause(c.buyout)?.amount||0}" data-neg-buyout="${n.id}">억</label><label>옵션 <select data-neg-option="${n.id}"><option value="none"${!c.option?' selected':''}>없음</option><option value="team"${c.option?.type==='team'?' selected':''}>팀 옵션</option><option value="player"${c.option?.type==='player'?' selected':''}>선수 옵션</option></select></label><label>약속 역할 <select data-neg-role="${n.id}">${SQUAD_ROLES.map(x=>`<option value="${x}"${c.promisedRole===x?' selected':''}>${SQUAD_ROLE_KO[x]}</option>`).join('')}</select></label></div><div class="controls"><button class="primary" data-neg-submit="${n.id}">제안 보내기</button>${n.counter?`<button class="ghost" data-neg-accept="${n.id}">역제안 그대로 수락</button>`:''}<button class="ghost" data-neg-cancel="${n.id}">협상 종료</button></div><p class="hint">방출 보상은 지역 사무국 공통 규정을 따릅니다.</p></div>`}).join('');
}
function negotiationTermsFromDom(nid){return {salary:+document.querySelector(`[data-neg-sal="${nid}"]`).value,years:+document.querySelector(`[data-neg-years="${nid}"]`).value,signingBonus:+document.querySelector(`[data-neg-sign="${nid}"]`).value,bonuses:{performance:+document.querySelector(`[data-neg-perf="${nid}"]`).value,title:+document.querySelector(`[data-neg-title="${nid}"]`).value,international:+document.querySelector(`[data-neg-intl="${nid}"]`).value},buyout:(+document.querySelector(`[data-neg-buyout="${nid}"]`).value||0)>0?{amount:+document.querySelector(`[data-neg-buyout="${nid}"]`).value,type:document.querySelector(`[data-neg-buyout-type="${nid}"]`).value}:null,option:document.querySelector(`[data-neg-option="${nid}"]`).value==='none'?null:{type:document.querySelector(`[data-neg-option="${nid}"]`).value},promisedRole:document.querySelector(`[data-neg-role="${nid}"]`).value}}
function bindNegotiationControls(act,allowed=()=>true){
  document.querySelectorAll('[data-neg-bid]').forEach(b=>b.onclick=()=>{if(!allowed())return;const n=negotiationStore(DB)[b.dataset.negBid];act(mTransferBid(DB,n.pid,+document.querySelector(`[data-neg-fee="${n.id}"]`).value,transferFeePlanFromDom(n.id,+document.querySelector(`[data-neg-fee="${n.id}"]`).value)))});
  document.querySelectorAll('[data-accept-seller]').forEach(b=>b.onclick=()=>{if(allowed())act(acceptSellerCounter(DB,b.dataset.acceptSeller))});
  document.querySelectorAll('[data-neg-submit]').forEach(b=>b.onclick=()=>{if(allowed())act(submitNegotiationOffer(DB,b.dataset.negSubmit,negotiationTermsFromDom(b.dataset.negSubmit)).msg)});
  document.querySelectorAll('[data-neg-accept]').forEach(b=>b.onclick=()=>{if(allowed())act(acceptNegotiationCounter(DB,b.dataset.negAccept).msg)});
  document.querySelectorAll('[data-neg-cancel]').forEach(b=>b.onclick=()=>{if(allowed())act(cancelNegotiation(DB,b.dataset.negCancel))});
}
